package com.farika.soundflow;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.android.controller.*;import java.util.*;import java.lang.reflect.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=android.app.Application.class)
public class MemoryUi164Test {
 LibraryUi163Test f;
 @Before public void setup()throws Exception{f=new LibraryUi163Test();f.setup();}
 @After public void cleanup(){f.cleanup();}
 @Test public void listReusesSameRowAndRebindsText()throws Exception{ActivityController<LibraryUi163Test.FakeMain> ctrl=f.screen("likes","");try{BaseAdapter adapter=(BaseAdapter)f.field(ctrl.get(),"adapter");ListView list=(ListView)f.field(ctrl.get(),"list");View row=adapter.getView(0,null,list);View reused=adapter.getView(1,row,list);assertSame(row,reused);boolean second=false;for(View v:f.all(reused))if(v instanceof TextView&&"Второй трек".contentEquals(((TextView)v).getText()))second=true;assertTrue(second);}finally{ctrl.destroy();}}
 @Test public void miniHasPreviousButtonAndCanRestorePreviousCommand()throws Exception{android.content.Context c=RuntimeEnvironment.getApplication();Library lib=new Library(c);Library.Track t=LibraryUi163Test.song("1","First");lib.upsert(t);lib.save();PlaybackCheckpoint.save(c,Arrays.asList(t.uri),0,0,false,false);ActivityController<LibraryUi163Test.FakeMain> ctrl=f.screen("likes","");try{View previous=null;for(View v:f.all(ctrl.get().getWindow().getDecorView()))if(android.text.TextUtils.equals("Предыдущий трек",v.getContentDescription()))previous=v;assertNotNull(previous);previous.performClick();Intent command=Shadows.shadowOf(ctrl.get()).getNextStartedService();assertNotNull(command);assertEquals("PREV",command.getAction());}finally{ctrl.destroy();}}
 @Test public void offlineQueueGetsRepeatAllContext()throws Exception{ActivityController<LibraryUi163Test.FakeMain> ctrl=f.screen("offline","");try{Method play=MainActivity.class.getDeclaredMethod("play",Library.Track.class,List.class);play.setAccessible(true);Library.Track t=LibraryUi163Test.song("1","First");play.invoke(ctrl.get(),t,Arrays.asList(t));Intent command=Shadows.shadowOf(ctrl.get()).getNextStartedService();assertNotNull(command);assertTrue(command.getBooleanExtra("playlistContext",false));}finally{ctrl.destroy();}}
 @Test public void homeHasNoReloadButtonButSupportsPullRefresh()throws Exception{ActivityController<LibraryUi163Test.FakeMain> ctrl=f.screen("likes","");try{Field page=MainActivity.class.getDeclaredField("page");page.setAccessible(true);page.set(ctrl.get(),"home");new HomeFeed(ctrl.get()).put(new HomeFeed(ctrl.get()).key("123","mix",true),Arrays.asList(LibraryUi163Test.song("1","First")),"Cached",0,0);Method build=MainActivity.class.getDeclaredMethod("build");build.setAccessible(true);build.invoke(ctrl.get());boolean pull=false;for(View v:f.all(ctrl.get().getWindow().getDecorView())){if(v instanceof PullRefreshLayout)pull=true;assertFalse(android.text.TextUtils.equals("Обновить подборку",v.getContentDescription()));}assertTrue(pull);}finally{ctrl.destroy();}}
 @Test public void openingSignedInLibraryDoesNotCreateHiddenBrowser()throws Exception{ActivityController<LibraryUi163Test.FakeMain> ctrl=f.screen("likes","");ctrl.start().resume();try{Shadows.shadowOf(Looper.getMainLooper()).idleFor(java.time.Duration.ofMillis(1000));assertNull(f.field(ctrl.get(),"accountWriter"));}finally{ctrl.pause().stop().destroy();}}
 @Test public void downloadButtonAnimatesOnlyWhileActualWorkRuns()throws Exception{ActivityController<LibraryUi163Test.FakeMain> ctrl=f.screen("likes","");try{DownloadActivityState.begin("123");Method update=MainActivity.class.getDeclaredMethod("updatePlayback");update.setAccessible(true);update.invoke(ctrl.get());DownloadIndicator icon=(DownloadIndicator)f.field(ctrl.get(),"downloadIndicator");assertNotNull(icon);assertTrue(icon.active());DownloadActivityState.end("123");update.invoke(ctrl.get());assertFalse(icon.active());}finally{DownloadActivityState.end("123");ctrl.destroy();}}
 @Test public void recycledPlaylistRowsKeepOfflineSummary()throws Exception{f.copy();new PlaylistCache(f.c).put("a","A","own",Arrays.asList(LibraryUi163Test.song("1","Saved")),false,"123");ActivityController<LibraryUi163Test.FakeMain> ctrl=f.screen("playlists","");try{BaseAdapter adapter=(BaseAdapter)f.field(ctrl.get(),"adapter");View row=adapter.getView(0,null,(ListView)f.field(ctrl.get(),"list"));boolean count=false;for(View v:f.all(row))if(v instanceof TextView&&((TextView)v).getText().toString().contains("1 / 1 на устройстве"))count=true;assertTrue(count);}finally{ctrl.destroy();}}

}
